public class Main {
    static boolean carPooling(int[][] trips, int capacity) {
        int[] counts = new int[1001];
        for (int[] trip : trips) {
            for (int loc = trip[1]; loc < trip[2]; loc++) {   // touch every location in the range
                counts[loc] += trip[0];
                if (counts[loc] > capacity) return false;
            }
        }
        return true;
    }
}

