def car_pooling(trips, capacity):
    diff = [0] * 1002
    for num, start, end in trips:
        diff[start] += num              # pickup begins here
        diff[end] -= num                 # drop-off ends it

    running = 0
    for change in diff:
        running += change                 # one sweep reconstructs the true passenger count
        if running > capacity:
            return False
    return True

